"""Capture a tested V15 candidate without publishing it."""
from pathlib import Path
import hashlib,json,datetime,subprocess
R=Path(__file__).resolve().parents[1];H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
subprocess.run(['node','tests/v15-scope.test.mjs'],cwd=R/'web',check=True)
paths=[R/'web/index.html']+[p for d in ['web/src','web/public']for p in(R/d).rglob('*')if p.is_file()]
rows=[{'path':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'sha256':H(p)}for p in sorted(paths)]
gate=json.loads((R/'tests/v15/final_gate_receipt.json').read_text())
assert gate['result']=='PASS' and gate['runtime_unchanged_during_gate'] is True
assert all(c['exit_code']==0 for c in gate['commands'])
assert {x['path']:x['sha256']for x in rows}==gate['runtime_hashes'], 'Runtime differs from the tested gate snapshot'
tree=hashlib.sha256(''.join(x['path']+'\0'+x['sha256']+'\n'for x in sorted(rows,key=lambda x:x['path'])).encode()).hexdigest()
anchors=['dist/malabar-hot-coast.html','dist/game.bundle.js','dist/ui-preview.html','dist/v15-ui-preview.html','web/package.json','web/package-lock.json','web/build-standalone.mjs','web/build-ui-preview.mjs','tests/v15/full_gate.log','tests/v15/final_gate_receipt.json','tests/v15/aircraft_visibility_metrics.json','tests/recovery/standalone_integrity.json','assets/helicopter/freeze.json','assets/airtime/ramp_manifest.json','docs/v15/model_contract.md','docs/v15/BROWSER_ACCEPTANCE_PLAN.md']
report={'candidate':'MALABAR V15 air support and authored ramp-airtime','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'base':'V14.1 Sites31 commit7a0bf2ca96ed0f9a18963cd6ad42498f361eb74c','runtime_tree_sha256':tree,'tree_algorithm':'SHA256 of sorted relative-path + NUL + file SHA256 + newline','runtime_files':rows,'anchors':{n:{'bytes':(R/n).stat().st_size,'sha256':H(R/n)}for n in anchors},'status':'Source/model/actual-GLB geometry and signal gates passed; new native WebGL/human/audio acceptance remains separate.','protected':'109 existing runtime files remain byte-identical, including all save/economy/story/UI-style modules and pre-existing model assets. Existing reverse traction fix retained.','scope':['Original civilian and police helicopters, independent rotors/searchlight, sparse anchored crossing and observational high-heat pursuit support','Two authored graded ramp decks, coherent player/AI lip departure/landing, side/rear contacts','One-time bounded clean-landing boost refill, truthful actual transfer feedback; no coin or save change','Original distance/pan/Doppler rotor synthesis, pause/mute lifecycle and opt-in diagnostics'],'limits':['Not the reference video full wall/ceiling/loop-driving system','Aircraft are kinematic game actors, not flight simulation; no new helicopter damage/arrest mechanic','Geometry/frustum/line-of-sight and numerical audio tests are not GPU/all-pixel/listening acceptance','No multiplayer integration or backend change','Original game art remains stylized, not a photoreal or AAA-equivalence claim'],'license':'Required OSM/Three/font notices and approved neutral original-material wording retained; no new reuse grant or historical-revocation claim. No user reference images/video included.'}
(R/'tests/release/V15_RELEASE.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'runtime_files':len(rows),'runtime_tree_sha256':tree,'standalone':report['anchors']['dist/malabar-hot-coast.html']},indent=2))
